const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
const money = value => value == null ? '—' : `₹${Number(value).toLocaleString('en-IN')}`;
const initials = value => String(value || 'O').trim().split(/\s+/).slice(0, 2).map(part => part[0]).join('').toUpperCase();
const fmtDate = value => value ? new Intl.DateTimeFormat('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(value)) : '—';
const timeLeft = value => { const ms = Math.max(0, Date.parse(value) - Date.now()); const hrs = Math.floor(ms / 3600000); const mins = Math.floor((ms % 3600000) / 60000); return `${hrs}h ${mins}m left`; };
const categoriesIcons = ['⌁', '◉', '▣', '◷', '◖', '♫', '⌂', '♨', '◒', '▱', '♢', '✎', '✦', '➤', '✧', '✳'];
const brandStyles = { JBL: ['#fff0ee', '#d34132'], Logitech: ['#f0f4ff', '#1769aa'], Milton: ['#e8f6fa', '#087c9b'], Wildcraft: ['#eff5e8', '#547c3c'], Samsung: ['#eaf1ff', '#174ea6'], Noise: ['#f5efff', '#6544b5'], Parker: ['#eff7f1', '#397a47'], HP: ['#eef7ff', '#087fc0'], boAt: ['#fff1e9', '#d96029'], Philips: ['#edf5ff', '#1652a0'] };
const state = { page: 'home', me: null, catalogAccess: false, products: [], categories: [], brands: [], brandDirectory: [], brandSearch: '', brandCategory: '', brandLetter: '', brandPage: 1, dealers: [], query: '', category: '', brand: '', city: '', maxPrice: '', inStock: false, modal: null, authMode: 'login', authRole: 'buyer', dashboard: null, dashSection: 'overview', mobileNav: false, mobileFilters: false, saved: [], notifications: [] };
