function routeFromLocation() {
  const storeRoute = parseBrandStoreRoute(window.location.hash); if (storeRoute) return storeRoute;
  const route = window.location.hash.slice(1).toLowerCase();
  if (route.startsWith('reset/')) return { page: 'reset', recoveryToken: route.slice(6) };
  if (route.startsWith('blog/')) return { page: 'article', articleSlug: route.slice(5) };
  return { page: ['brands', 'products', 'dealers', 'how', 'auth', 'dashboard', 'mission', 'vision', 'blogs', 'help', 'recover', 'enquiry-cart'].includes(route) ? route : 'home' };
}
function pageURL() {
  return state.page === 'brand-store' ? brandStoreURL(state.storeBrand, state.storeSupplierId) : state.page === 'home' ? window.location.pathname : state.page === 'article' ? `#blog/${state.articleSlug || ''}` : `#${state.page}`;
}

async function api(path, options = {}) {
  const response = await fetch(path, { credentials: 'same-origin', ...options, headers: { ...(options.body ? { 'content-type': 'application/json' } : {}), ...(options.headers || {}) } });
  const type = response.headers.get('content-type') || '';
  const result = type.includes('application/json') ? await response.json() : null;
  if (!response.ok) throw new Error(result?.error || 'Something went wrong. Please try again.');
  return result;
}
const post = (path, data) => api(path, { method: 'POST', body: JSON.stringify(data) });
function toast(message, type = 'success') {
  const host = $('#toast-root'); const node = document.createElement('div'); node.className = `toast ${type}`; node.textContent = message; host.append(node); setTimeout(() => node.remove(), 3600);
}
async function load() {
  try {
    const route = routeFromLocation();
    state.page = route.page; state.articleSlug = route.articleSlug || ''; state.storeBrand = route.storeBrand || ''; state.storeSupplierId = route.storeSupplierId || '';
    const [me, catalog, config] = await Promise.all([api('/api/me'), api('/api/catalog'), api('/api/config')]); state.config = config; state.recoveryToken = route.recoveryToken || '';
    state.me = me.user; state.saved = state.me?.savedProducts || []; state.notifications = me.notifications || []; applyCatalog(catalog);
    if (!state.me && ['products', 'dealers', 'dashboard', 'enquiry-cart'].includes(state.page)) { state.page = 'auth'; state.authMode = 'login'; }
    if (state.me && (state.page === 'home' || state.page === 'dashboard')) { state.page = 'dashboard'; await refreshDashboard(); }
    if (state.me && state.page === 'enquiry-cart') await refreshDashboard();
    render();
  } catch (error) { root.innerHTML = `<main class="boot-screen"><strong>OfNeeds B2B couldn’t load</strong><span>${esc(error.message)}</span></main>`; }
}
function applyCatalog(catalog) { state.catalogAccess = Boolean(catalog.catalogAccess); state.products = catalog.products || []; state.categories = catalog.categories || []; state.brands = catalog.brands || []; state.brandDirectory = catalog.brandDirectory || []; state.dealers = catalog.dealers || []; }
async function refreshCatalog() { const data = await api('/api/catalog'); applyCatalog(data); }
async function refreshAccount() { const data = await api('/api/me'); state.me = data.user; state.saved = state.me?.savedProducts || []; state.notifications = data.notifications || []; }
async function refreshDashboard() { if (!state.me) return; state.dashboard = await api('/api/dashboard'); }
async function go(page, options = {}) {
  state.page = !state.me && ['products', 'dealers', 'dashboard', 'enquiry-cart'].includes(page) ? 'auth' : page; state.mobileNav = false; state.mobileFilters = false;
  state.modal = null;
  if (options.articleSlug !== undefined) state.articleSlug = options.articleSlug;
  if (options.recoveryToken !== undefined) state.recoveryToken = options.recoveryToken;
  if (options.storeBrand !== undefined) { state.storeBrand = options.storeBrand; state.storeSort = 'featured'; }
  if (options.storeSupplierId !== undefined) state.storeSupplierId = options.storeSupplierId;
  if (!options.fromLocation && (window.location.hash || window.location.pathname) !== pageURL()) history.pushState(null, '', pageURL());
  if (options.query !== undefined) state.query = options.query;
  if (page === 'dashboard') { if (!state.me) { state.page = 'auth'; state.authMode = 'login'; } else { try { await refreshDashboard(); } catch (error) { toast(error.message, 'error'); } } }
  if (['products', 'brands', 'dealers', 'brand-store'].includes(page)) await refreshCatalog();
  if (page === 'enquiry-cart' && state.me) { await refreshCatalog(); await refreshDashboard(); }
  render(); window.scrollTo({ top: 0, behavior: 'instant' });
}
function brandStyle(brand) { const style = brandStyles[brand] || ['#eef3fc', '#48658c']; return `--brand-tint:${style[0]};--brand-ink:${style[1]}`; }
function brandMonogram(brand) { return ({ Logitech: 'logi', Samsung: 'S', 'American Tourister': 'AT', Milton: 'M', JBL: 'JBL' })[brand] || String(brand || 'B').slice(0, 2).toUpperCase(); }
function dealerFor(product) { return product?.dealer || {}; }
function authorizedBuyer() { return !!state.me && state.me.role === 'buyer' && state.me.status === 'approved' && state.me.gstStatus === 'verified'; }
function canSeePrice() { return authorizedBuyer(); }
function header() {
  const links = state.me ? [['Products', 'products'], ['Brands', 'brands'], ['Suppliers', 'dealers'], ['How it works', 'how'], ['About', 'mission'], ['Journal', 'blogs']] : [['Explore brands', 'brands'], ['How it works', 'how'], ['About', 'mission'], ['Journal', 'blogs']];
  const nav = links.map(([label, page]) => `<a href="${page === 'home' ? '#' : '#' + page}" data-page="${page}" ${state.page === page || (page === 'blogs' && state.page === 'article') ? 'aria-current="page"' : ''}>${label}</a>`).join('');
  return `<header class="topbar"><div class="topbar-inner">
    <a href="#" class="brand-lockup" data-page="home" aria-label="OfNeeds home"><img class="brand-logo-image" src="/assets/ofneeds-wordmark.svg" width="190" height="64" alt="OfNeeds"></a>
    <nav aria-label="Main navigation" class="main-nav ${state.mobileNav ? 'open' : ''}">${nav}</nav>
    <div class="nav-right">${state.me ? '<button class="user-menu" data-action="account" aria-label="My workspace"><span class="avatar">' + esc(initials(state.me.name)) + '</span><span class="nav-user-name">My workspace</span></button>' : '<button class="btn btn-ghost" data-action="login">Log in</button><button class="btn btn-primary" data-action="register" data-role="buyer">Join OfNeeds <span aria-hidden="true">↗</span></button>'}
      <button class="mobile-menu" data-action="mobile-menu" aria-label="Toggle navigation" aria-expanded="${state.mobileNav}">${state.mobileNav ? '×' : '☰'}</button>
    </div>
  </div></header>`;
}
function footer() {
  return `<footer class="simple-footer"><div class="footer-grid"><div><a href="#" data-page="home" aria-label="OfNeeds home"><img src="/assets/ofneeds-wordmark.svg" width="190" height="64" alt="OfNeeds"></a><p>The right connections for<br>your next gifting brief.</p></div><div><strong>Discover</strong><a href="#brands" data-page="brands">Brand directory</a><a href="#how" data-page="how">How it works</a><a href="#blogs" data-page="blogs">Sourcing journal</a></div><div><strong>OfNeeds</strong><a href="#mission" data-page="mission">Our mission</a><a href="#vision" data-page="vision">Our vision</a><a href="#help" data-page="help">Help & verification</a></div><div><strong>Get connected</strong>${state.me ? '<a href="#dashboard" data-page="dashboard">My workspace</a>' : '<button data-action="register" data-role="buyer">Join as a buyer</button><button data-action="register" data-role="dealer">Join as a supplier</button>'}<button data-action="book-demo">Request a walkthrough</button><a href="#help" data-page="help">Account assistance</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} OfNeeds</span><a href="#help" data-page="help">Data, access & stock hold information</a><span>Business sourcing, made clearer.</span></div></footer>`;
}

function productImage(product) {
  const authentic = product.image && !product.image.includes('images.unsplash.com');
  return authentic ? `<img src="${esc(product.image)}" alt="${esc(product.name)}" width="480" height="360" loading="lazy" decoding="async">` : `<div class="product-image-pending"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.2" aria-hidden="true"><path d="m3 7 9-4 9 4v10l-9 4-9-4zM3 7l9 5 9-5M12 12v9"/></svg><strong>${esc(product.brand)}</strong><span>Product photo pending</span></div>`;
}
function productCard(product) {
  const dealer = dealerFor(product), hidden = !canSeePrice(), available = Number(product.available || 0), saved = state.saved.includes(product.id), holdable = available >= product.moq;
  return `<article class="product-card"><div class="product-photo"><button class="product-image-button" data-action="brand-store" data-brand="${esc(product.brand)}" data-supplier="${esc(product.dealerId)}" aria-label="Open ${esc(product.brand)} store for ${esc(dealer.businessName)}">${productImage(product)}<span class="store-entry-hint">Explore ${esc(product.brand)} store →</span></button><span class="photo-badge ${!available ? 'unavailable' : product.lowStock ? 'low' : ''}">${available ? (product.lowStock ? 'Low stock' : 'In stock') : 'Out of stock'}</span><button class="save-button ${saved ? 'saved' : ''}" data-action="save" data-id="${esc(product.id)}" aria-label="${saved ? 'Remove saved' : 'Save'} ${esc(product.name)}" aria-pressed="${saved}">${saved ? '♥' : '♡'}</button></div><div class="product-content"><div class="product-brand"><a class="brand-store-link" href="${esc(brandStoreURL(product.brand, product.dealerId))}" data-action="brand-store" data-brand="${esc(product.brand)}" data-supplier="${esc(product.dealerId)}">${esc(product.brand)}</a>${dealer.verified ? ' <span class="verified-dot" title="Brand authorization reviewed">✓</span>' : ''}</div><h3 class="product-name"><button data-action="product-detail" data-id="${esc(product.id)}">${esc(product.name)}</button></h3><div class="product-model">Model ${esc(product.model || 'Not specified')}</div><div class="price-line">${hidden ? '<span class="price-hidden">B2B price · verified buyers</span>' : `<span class="product-price">${money(product.price)}<small> / unit</small></span><span class="product-mrp">${money(product.mrp)}</span>`}</div><p class="tax-note">${hidden ? 'Business access required for pricing' : `Excludes ${Number(product.gst || 0)}% GST`}</p><div class="product-detail-row"><span>MOQ <b>${Number(product.moq).toLocaleString('en-IN')} units</b></span><span class="${!available ? 'stock-none' : product.lowStock ? 'stock-low' : 'stock-good'}">${available.toLocaleString('en-IN')} available</span></div><p class="product-logistics">Lead time: ${esc(product.leadTime || 'Ask supplier')}</p><div class="product-dealer"><span class="dealer-logo">${esc(initials(dealer.businessName))}</span><span class="dealer-meta"><strong>${esc(dealer.businessName || 'Supplier')}</strong><span>${esc(dealer.city || 'India')}${dealer.state ? `, ${esc(dealer.state)}` : ''}</span></span></div>${sourcing.card(product)}<div class="card-actions"><button class="btn btn-outline" data-action="reserve" data-id="${esc(product.id)}" ${holdable ? '' : 'disabled'}>${holdable ? 'Request stock hold' : available ? 'Below hold MOQ' : 'Stock unavailable'}</button><button class="btn btn-ghost" data-action="rfq" data-id="${esc(product.id)}" aria-label="Request a quote for ${esc(product.name)}">Quote →</button></div></div></article>`;
}

function brandTile(brand, count) { const name = typeof brand === 'string' ? brand : brand.name; return `<div class="brand-tile" data-action="brand-filter" data-brand="${esc(name)}"><span class="brand-emblem" style="${brandStyle(name)}">${esc(brandMonogram(name))}</span><span><strong>${esc(name)}</strong><small>${count || 0} products · verified supply</small></span></div>`; }
function sectionHead(kicker, title, subtitle, link = '', page = '') { return `<div class="section-head"><div><span class="section-kicker">${kicker}</span><h2 class="section-title">${title}</h2><p class="section-subtitle">${subtitle}</p></div>${link ? `<a class="text-link" href="#${page}" data-page="${page}">${link} <span>↗</span></a>` : ''}</div>`; }
function homeLineIcon(name) {
  const paths = {
    shield: '<path d="M12 3 20 6v5c0 5-3.4 8.2-8 10-4.6-1.8-8-5-8-10V6l8-3Z"/><path d="m8.5 12 2.3 2.3 4.8-5"/>',
    search: '<circle cx="10.5" cy="10.5" r="6.5"/><path d="m15.5 15.5 5 5M7.5 10.5h6M10.5 7.5v6"/>',
    stock: '<path d="M3 7h11v11H3zM14 11h4l3 3v4h-7z"/><circle cx="7" cy="19" r="2"/><circle cx="18" cy="19" r="2"/><path d="M6 10h5M6 13h4"/>',
    quote: '<path d="M4 5.5A2.5 2.5 0 0 1 6.5 3h11A2.5 2.5 0 0 1 20 5.5v8a2.5 2.5 0 0 1-2.5 2.5H11l-5 4v-4.3A2.5 2.5 0 0 1 4 13.5z"/><path d="M8 8h8M8 11.5h5"/>'
  };
  return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name] || paths.shield}</svg>`;
}
