  if (state.dashSection === 'enquiries') return `<div class="dash-title-row"><div><h1>RFQs & enquiries</h1><p>Review quote requests and responses across the network.</p></div></div><div class="dash-panel"><div class="panel-head"><h3>All RFQs (${data.enquiries.length})</h3></div><div class="panel-body">${data.enquiries.length ? enquiryGroups(data.enquiries, enquiryRow) : '<div class="empty-products">No enquiries yet.</div>'}</div></div>`;
